<?php
require_once __DIR__ . '/../includes/config.php';
if(session_status()===PHP_SESSION_NONE)session_start();
$riderId=(int)($_SESSION['rider_id']??$_SESSION['rider_user_id']??0);if(!$riderId){header('Location: login.php');exit;}
$msg='';$err='';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['submit_cod'])){
 $amount=(float)($_POST['amount']??0);$method=trim($_POST['payment_method']??'bank_transfer');$ref=trim($_POST['transaction_reference']??'');$f=$_FILES['proof']??null;
 if($amount<=0)$err='Enter a valid COD amount.';elseif(!$f||empty($f['name']))$err='Please upload the payment screenshot.';else{
  $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ok=['image/jpeg','image/png','image/webp'];
  if($f['error']!==UPLOAD_ERR_OK||!in_array($mime,$ok,true)||$f['size']>5*1024*1024)$err='Upload a JPG, PNG or WEBP image up to 5MB.';else{
   $dir=__DIR__.'/../uploads/cod_proofs';if(!is_dir($dir))mkdir($dir,0755,true);$ext=$mime==='image/png'?'png':($mime==='image/webp'?'webp':'jpg');$name='rider_'.$riderId.'_'.bin2hex(random_bytes(8)).'.'.$ext;$relative='uploads/cod_proofs/'.$name;
   if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))$err='Unable to save screenshot.';else{
    $q=$conn->prepare("INSERT INTO rider_cod_settlements (rider_id,amount,payment_method,transaction_reference,proof_image,status) VALUES (?,?,?,?,?,'pending')");$q->bind_param('idsss',$riderId,$amount,$method,$ref,$relative);
    if(!$q->execute())$err='COD settlement could not be submitted. Run the payment verification SQL first.';else$msg='COD payment submitted successfully. Admin verification is pending.';$q->close();
   }
  }
 }
}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>COD Settlement | Humsafar</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>*{box-sizing:border-box}body{margin:0;background:#fff8fb;font-family:Segoe UI,Arial;color:#292929}.box{max-width:650px;margin:55px auto;padding:28px;background:#fff;border:1px solid #f0dce5;border-radius:18px}.icon{width:54px;height:54px;border-radius:14px;background:#fff0f5;color:#ed0038;display:grid;place-items:center;font-size:22px}.box h1{font-size:24px;margin:14px 0 5px}.sub{color:#888;font-size:12px;margin-bottom:22px}.alert{padding:12px;border-radius:9px;font-size:11px;font-weight:700;margin-bottom:15px}.ok{background:#e7f8ed;color:#176c36}.err{background:#fff0f3;color:#a0002d}.field{margin:14px 0}.field label{display:block;font-size:10px;font-weight:800;margin-bottom:6px}.input{width:100%;height:43px;border:1px solid #e6d6dd;border-radius:9px;padding:0 12px}.upload{border:2px dashed #efcbd8;border-radius:12px;padding:25px;text-align:center;background:#fffafd}.upload i{font-size:28px;color:#ed0038}.upload p{font-size:10px;color:#888}.btn{width:100%;height:44px;border:0;border-radius:9px;background:#ed0038;color:#fff;font-weight:800;cursor:pointer}.note{font-size:10px;color:#777;background:#fff5d9;border:1px solid #f2df9d;border-radius:9px;padding:10px;margin-bottom:15px}</style></head><body><div class="box"><div class="icon"><i class="fa-solid fa-motorcycle"></i></div><h1>COD Payment Settlement</h1><div class="sub">Submit the COD cash amount you collected and the screenshot of the payment sent to Humsafar.</div><div class="note"><i class="fa-solid fa-circle-info"></i> Your settlement stays <b>Pending</b> until Admin verifies it.</div><?php if($msg):?><div class="alert ok"><i class="fa-solid fa-circle-check"></i> <?=h($msg)?></div><?php endif;?><?php if($err):?><div class="alert err"><i class="fa-solid fa-circle-exclamation"></i> <?=h($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><div class="field"><label>COD Amount (PKR) *</label><input class="input" type="number" name="amount" min="1" step="0.01" required></div><div class="field"><label>Payment Method</label><select class="input" name="payment_method"><option value="bank_transfer">Bank Transfer</option><option value="jazzcash">JazzCash</option><option value="easypaisa">Easypaisa</option></select></div><div class="field"><label>Transaction Reference</label><input class="input" name="transaction_reference" placeholder="Transaction ID / reference"></div><div class="field"><label>Payment Screenshot *</label><div class="upload"><i class="fa-solid fa-cloud-arrow-up"></i><p>JPG, PNG or WEBP — maximum 5MB</p><input type="file" name="proof" accept="image/jpeg,image/png,image/webp" required></div></div><button class="btn" name="submit_cod"><i class="fa-solid fa-paper-plane"></i> Submit COD Payment</button></form></div></body></html>